/* Pagina Brand integrata dentro il sito statico locale.
   CSS originale dell'HTML fornito, isolato sotto .brand-integrated per non modificare header/footer globali. */


.brand-integrated{--forest:#0d2b18; --forest-2:#123820; --green:#1a4a2e; --green-2:#2a6e3e; --green-3:#3d8a52;
  --sage:#eef5f0; --sage-2:#f6faf7; --paper:#fafaf8; --paper-2:#f4f4f0; --white:#fff;
  --amber:#b8903c; --amber-2:#d2ad5b; --amber-l:#fdf6e8;
  --ink:#0d2b18; --ink-2:#2c3e30; --ink-3:#5a6e5e; --ink-4:#8fa094;
  --silver:#b4b4ac; --silver-2:#d0d0c8; --silver-3:#e8e8e2;
  --border:rgba(13,43,24,.10); --border-2:rgba(13,43,24,.16); --gold-border:rgba(184,144,60,.25);
  --menopausa:#c94478; --beauty:#1a6b30; --circolo:#126b52; --energia:#a86010;
  --menopausa-l:#fdf0f5; --beauty-l:#eaf5ec; --circolo-l:#e4f5ef; --energia-l:#faeedd;}


.brand-integrated *{box-sizing:border-box;margin:0;padding:0}
.brand-integrated{scroll-behavior:smooth}
.brand-integrated{font-family:"Montserrat",sans-serif;background:var(--paper);color:var(--ink);min-height:100vh}
.brand-integrated .page{display:none;animation:fade .28s ease}
.brand-integrated .page.active{display:block}
@keyframes fade;


.brand-integrated.no-scroll{overflow:hidden}
.brand-integrated .container{max-width:1240px;margin:0 auto}
.brand-integrated .accent{color:var(--amber)}
.brand-integrated .serif{font-family:"Cormorant Garamond",serif}
.brand-integrated .script{font-family:"Great Vibes",cursive}
.brand-integrated .muted{color:var(--ink-3)}
.brand-integrated button{font-family:"Montserrat",sans-serif}


/* NAV */


.brand-integrated nav{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.96);backdrop-filter:blur(12px);border-bottom:1px solid var(--gold-border);display:flex;align-items:center;justify-content:space-between;padding:0 44px;height:70px}
.brand-integrated .logo-box{display:inline-flex;flex-direction:column;align-items:center;justify-content:center;border:1.5px solid currentColor;padding:4px 10px 5px;gap:1px;cursor:pointer;color:var(--green)}
.brand-integrated .logo-08{font-family:"Cormorant Garamond",serif;font-size:22px;font-weight:400;line-height:1;letter-spacing:-.01em}
.brand-integrated .logo-nt{font-size:6px;font-weight:300;letter-spacing:.26em;text-transform:uppercase;line-height:1;white-space:nowrap}
.brand-integrated .n-links{display:flex;align-items:center;height:100%;gap:1px}
.brand-integrated .nl{height:70px;padding:0 10px;border:none;background:transparent;font-size:9px;font-weight:500;letter-spacing:.13em;text-transform:uppercase;color:var(--ink-3);cursor:pointer;border-bottom:2px solid transparent;transition:.18s}
.brand-integrated .nl:hover, .brand-integrated .nl.active{color:var(--green);border-bottom-color:var(--amber)}
.brand-integrated .n-cta{font-size:9px;font-weight:600;letter-spacing:.18em;text-transform:uppercase;padding:10px 18px;border:1px solid var(--green);background:transparent;color:var(--green);cursor:pointer;transition:.18s}
.brand-integrated .n-cta:hover{background:var(--green);color:#fff}
.brand-integrated .mobile-toggle{display:none;border:0;background:transparent;color:var(--green);font-size:25px;cursor:pointer}
.brand-integrated .nav-overlay{display:none}


/* HERO */


.brand-integrated .hero{background:radial-gradient(circle at 72% 28%,rgba(184,144,60,.13),transparent 28%),linear-gradient(135deg,var(--forest) 0%,#092212 100%);border-bottom:1px solid var(--gold-border)}
.brand-integrated .hero-grid{display:grid;grid-template-columns:1.02fr .98fr;min-height:620px}
.brand-integrated .hero-l{padding:86px 58px 82px 48px;display:flex;flex-direction:column;justify-content:center;border-right:.5px solid rgba(184,144,60,.18)}
.brand-integrated .hero-r{padding:64px 48px;display:flex;align-items:center;justify-content:center}
.brand-integrated .eyebrow{font-size:9px;font-weight:500;letter-spacing:.28em;text-transform:uppercase;color:var(--amber);display:flex;gap:10px;align-items:center;margin-bottom:18px}
.brand-integrated .eyebrow:before{content:"";width:24px;height:.5px;background:var(--amber);opacity:.75}
.brand-integrated .eyebrow.light{color:rgba(184,144,60,.72)}
.brand-integrated .h-display{font-family:"Cormorant Garamond",serif;font-size:64px;font-weight:300;line-height:1.03;letter-spacing:-.02em;color:var(--silver-3);margin-bottom:24px}
.brand-integrated .h-display em{font-style:italic;color:var(--amber)}
.brand-integrated .h-body{font-size:13px;font-weight:300;color:rgba(253,246,232,.66);line-height:1.9;max-width:520px;margin-bottom:34px}
.brand-integrated .h-btns{display:flex;gap:12px;flex-wrap:wrap}
.brand-integrated .btn-gold, .brand-integrated .btn-outline-dark, .brand-integrated .btn-green, .brand-integrated .btn-outline{font-size:9px;font-weight:600;letter-spacing:.18em;text-transform:uppercase;padding:13px 26px;cursor:pointer;transition:.18s;border:1px solid transparent}
.brand-integrated .btn-gold{background:var(--amber);color:var(--forest);border-color:var(--amber)}
.brand-integrated .btn-gold:hover{background:var(--amber-2)}
.brand-integrated .btn-outline-dark{background:transparent;color:rgba(253,246,232,.78);border-color:rgba(253,246,232,.22)}
.brand-integrated .btn-outline-dark:hover{border-color:rgba(253,246,232,.55);color:#fff}
.brand-integrated .btn-green{background:var(--green);color:#fff;border-color:var(--green)}
.brand-integrated .btn-green:hover{background:var(--green-2)}
.brand-integrated .btn-outline{background:transparent;color:var(--green);border-color:var(--green)}
.brand-integrated .btn-outline:hover{background:var(--green);color:#fff}
.brand-integrated .hero-note{margin-top:34px;border-left:1px solid rgba(184,144,60,.42);padding-left:18px;color:rgba(253,246,232,.43);font-size:10.5px;font-weight:300;line-height:1.8}
.brand-integrated .hero-stage{width:100%;max-width:480px;min-height:440px;position:relative;display:flex;align-items:flex-end;justify-content:center;padding:40px 20px}
.brand-integrated .stage-ring{position:absolute;inset:45px;border:1px solid rgba(184,144,60,.15);border-radius:50%;filter:blur(.1px)}
.brand-integrated .stage-light{position:absolute;width:74%;height:74%;border-radius:50%;background:radial-gradient(circle,rgba(184,144,60,.16),transparent 62%);top:11%;left:13%}
.brand-integrated .bottle-row{display:flex;align-items:flex-end;justify-content:center;gap:12px;position:relative;z-index:2}
.brand-integrated .bottle{width:86px;height:228px;border-radius:7px 7px 5px 5px;position:relative;background:linear-gradient(90deg,#0c0f0d,#1d2b22 28%,#355241 50%,#172218 76%,#070907);box-shadow:0 28px 46px rgba(0,0,0,.28);border:1px solid rgba(255,255,255,.06);overflow:hidden}
.brand-integrated .bottle.small{width:72px;height:194px}
.brand-integrated .bottle.tall{height:248px}
.brand-integrated .cap{position:absolute;top:0;left:0;right:0;height:29px;background:linear-gradient(90deg,#7f7f78,#dadad1 38%,#a4a49d 72%,#696964);border-bottom:1px solid rgba(0,0,0,.25)}
.brand-integrated .label{position:absolute;left:8px;right:8px;top:55px;bottom:22px;background:linear-gradient(180deg,rgba(255,255,255,.9),rgba(250,250,245,.92));display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:10px 6px;border:1px solid rgba(184,144,60,.23)}
.brand-integrated .label .l08{font-family:"Cormorant Garamond",serif;font-size:28px;color:var(--green);line-height:1}
.brand-integrated .label .lname{font-size:7px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--ink);line-height:1.35;margin-top:7px}
.brand-integrated .label .lbar{height:3px;width:38px;margin-top:9px}
.brand-integrated .l-men{background:var(--menopausa)}
.brand-integrated .l-bea{background:var(--beauty)}
.brand-integrated .l-cir{background:var(--circolo)}
.brand-integrated .l-ene{background:var(--energia)}


/* TRUST */


.brand-integrated .trust-bar{background:var(--forest);border-top:.5px solid rgba(184,144,60,.25);border-bottom:1px solid var(--amber);padding:15px 48px}
.brand-integrated .trust-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border-left:.5px solid rgba(184,144,60,.16)}
.brand-integrated .trust-item{display:flex;gap:12px;align-items:flex-start;padding:0 18px;border-right:.5px solid rgba(184,144,60,.16)}
.brand-integrated .trust-item i{color:var(--amber);font-size:16px;margin-top:2px}
.brand-integrated .trust-title{font-size:10px;text-transform:uppercase;letter-spacing:.15em;color:rgba(255,255,255,.76);font-weight:600;margin-bottom:3px}
.brand-integrated .trust-txt{font-size:10.2px;color:rgba(253,246,232,.42);line-height:1.55;font-weight:300}


/* SECTIONS */


.brand-integrated .s{padding:88px 48px}
.brand-integrated .s-alt{background:var(--paper-2)}
.brand-integrated .s-dark{background:var(--forest)}
.brand-integrated .sec-h{font-family:"Cormorant Garamond",serif;font-size:44px;font-weight:300;line-height:1.13;letter-spacing:-.01em;color:var(--ink)}
.brand-integrated .sec-h em{font-style:italic;color:var(--green-2)}
.brand-integrated .sec-h.light{color:#f0ede8}
.brand-integrated .sec-h.light em{color:var(--amber)}
.brand-integrated .sec-sub{font-size:12.5px;font-weight:300;color:var(--ink-3);line-height:1.9;max-width:680px;margin-top:16px}
.brand-integrated .sec-sub.light{color:rgba(253,246,232,.52)}
.brand-integrated .section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:40px;margin-bottom:46px}
.brand-integrated .section-head .sec-sub{max-width:480px;margin-top:0}
.brand-integrated .script-title{font-family:"Great Vibes",cursive;font-size:32px;color:var(--green-2);display:block;margin-bottom:4px}


/* PRODUCT CARDS */


.brand-integrated .p-grid{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--border-2);background:#fff}
.brand-integrated .p-card{background:#fff;border-right:1px solid var(--border-2);position:relative;transition:.18s;display:flex;flex-direction:column}
.brand-integrated .p-card:last-child{border-right:0}
.brand-integrated .p-card:hover{background:var(--sage-2);transform:translateY(-2px)}
.brand-integrated .p-top{height:218px;display:flex;align-items:center;justify-content:center;position:relative;border-bottom:1px solid var(--border-2);overflow:hidden}
.brand-integrated .p-top:after{content:"";position:absolute;inset:auto -30px -60px -30px;height:120px;background:rgba(255,255,255,.38);transform:rotate(-3deg)}
.brand-integrated .p-tag{position:absolute;top:15px;left:15px;font-size:8px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;padding:5px 10px;z-index:3}
.brand-integrated .mini-bottle{width:56px;height:142px;border-radius:5px;background:linear-gradient(90deg,#111,#263a2c 50%,#0b0e0b);position:relative;z-index:2;box-shadow:0 18px 34px rgba(0,0,0,.15);overflow:hidden}
.brand-integrated .mini-bottle:before{content:"";position:absolute;top:0;left:0;right:0;height:19px;background:linear-gradient(90deg,#8a8a84,#e5e5db 45%,#97978f)}
.brand-integrated .mini-label{position:absolute;left:6px;right:6px;top:39px;bottom:14px;background:#fff;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;border:1px solid rgba(184,144,60,.18)}
.brand-integrated .mini-label b{font-family:"Cormorant Garamond",serif;font-size:18px;color:var(--green)}
.brand-integrated .mini-label span{font-size:5.2px;line-height:1.3;text-transform:uppercase;font-weight:700;letter-spacing:.12em;color:var(--ink);padding:0 3px}
.brand-integrated .p-body{padding:24px 24px 26px;display:flex;flex-direction:column;flex:1}
.brand-integrated .p-name{font-family:"Cormorant Garamond",serif;font-size:25px;line-height:1.14;font-weight:400;margin-bottom:11px;color:var(--ink)}
.brand-integrated .p-desc{font-size:11.5px;font-weight:300;color:var(--ink-3);line-height:1.75;margin-bottom:16px}
.brand-integrated .target-box{border-left:2px solid var(--amber);padding:10px 0 10px 12px;background:linear-gradient(90deg,rgba(184,144,60,.06),transparent);font-size:10.5px;line-height:1.65;color:var(--ink-3);font-weight:300;margin-bottom:16px}
.brand-integrated .p-ings{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:18px}
.brand-integrated .ing{font-size:9.2px;font-weight:400;padding:4px 8px;background:var(--sage-2);color:var(--green-2);border:.5px solid rgba(42,110,62,.18)}
.brand-integrated .p-foot{margin-top:auto;border-top:1px solid var(--border);padding-top:14px;display:flex;justify-content:space-between;gap:12px;align-items:center}
.brand-integrated .p-detail{font-size:9.2px;font-weight:300;color:var(--ink-4);line-height:1.45}
.brand-integrated .p-cta{border:0;background:transparent;display:flex;align-items:center;gap:5px;font-size:9px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--green-2);cursor:pointer;white-space:nowrap}
.brand-integrated .p-cta i{font-size:13px;transition:.18s}
.brand-integrated .p-card:hover .p-cta i{transform:translateX(3px)}


/* METHOD */


.brand-integrated .method-grid{display:grid;grid-template-columns:repeat(4,1fr);border:.5px solid rgba(184,144,60,.22);margin-top:48px}
.brand-integrated .method-step{padding:34px 26px;border-right:.5px solid rgba(184,144,60,.14);background:rgba(255,255,255,.04)}
.brand-integrated .method-step:last-child{border-right:0}
.brand-integrated .method-n{font-family:"Cormorant Garamond",serif;font-size:48px;font-style:italic;font-weight:300;color:rgba(184,144,60,.28);line-height:1;margin-bottom:18px}
.brand-integrated .method-title{font-size:10.5px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:rgba(255,255,255,.75);margin-bottom:10px}
.brand-integrated .method-body{font-size:11.2px;font-weight:300;line-height:1.8;color:rgba(253,246,232,.46)}


/* TRANSPARENCY */


.brand-integrated .trans-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:42px;align-items:start}
.brand-integrated .proof-list{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.brand-integrated .proof-card{background:#fff;border:1px solid var(--border-2);padding:22px;min-height:160px}
.brand-integrated .proof-card i{font-size:22px;color:var(--amber);margin-bottom:14px}
.brand-integrated .proof-title{font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--ink);margin-bottom:8px}
.brand-integrated .proof-body{font-size:11.4px;font-weight:300;color:var(--ink-3);line-height:1.75}
.brand-integrated .reg-box{background:var(--forest);padding:34px;border:1px solid var(--gold-border);position:sticky;top:92px}
.brand-integrated .reg-box .sec-h{font-size:34px;color:#f0ede8;margin-bottom:18px}
.brand-integrated .reg-box p{font-size:11.8px;font-weight:300;line-height:1.85;color:rgba(253,246,232,.52);margin-bottom:16px}
.brand-integrated .reg-box ul{list-style:none;margin-top:18px}
.brand-integrated .reg-box li{font-size:10.4px;color:rgba(253,246,232,.64);line-height:1.75;border-top:.5px solid rgba(184,144,60,.15);padding:9px 0}
.brand-integrated .reg-box li:before{content:"•";color:var(--amber);margin-right:9px}


/* FOUNDER */


.brand-integrated .founder-grid{display:grid;grid-template-columns:.92fr 1.08fr;gap:60px;align-items:center}
.brand-integrated .founder-card{background:linear-gradient(160deg,var(--forest),#092212);min-height:390px;border:1px solid var(--gold-border);display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden}
.brand-integrated .founder-card:before{content:"";position:absolute;width:320px;height:320px;border-radius:50%;background:radial-gradient(circle,rgba(184,144,60,.16),transparent 62%)}
.brand-integrated .founder-mark{position:relative;text-align:center;color:rgba(232,232,226,.48)}
.brand-integrated .founder-mark .big{font-family:"Cormorant Garamond",serif;font-size:104px;line-height:1;font-weight:300}
.brand-integrated .founder-mark .small{font-size:10px;letter-spacing:.34em;text-transform:uppercase}
.brand-integrated .quote{font-family:"Cormorant Garamond",serif;font-size:25px;font-weight:300;font-style:italic;line-height:1.55;color:var(--green);border-left:2px solid var(--amber);padding-left:22px;margin:24px 0}
.brand-integrated .body-copy{font-size:12.2px;font-weight:300;line-height:1.95;color:var(--ink-3)}
.brand-integrated .body-copy p{margin-bottom:14px}
.brand-integrated .signature{font-family:"Great Vibes",cursive;font-size:34px;color:var(--green-2);margin-top:18px}


/* BLOG */


.brand-integrated .blog-grid{display:grid;grid-template-columns:1.25fr 1fr 1fr;gap:0;border:1px solid rgba(184,144,60,.18)}
.brand-integrated .blog-card{background:rgba(255,255,255,.04);border-right:.5px solid rgba(184,144,60,.14);cursor:pointer;transition:.18s}
.brand-integrated .blog-card:last-child{border-right:0}
.brand-integrated .blog-card:hover{background:rgba(255,255,255,.07)}
.brand-integrated .blog-vis{height:160px;border-bottom:.5px solid rgba(184,144,60,.14);display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.035)}
.brand-integrated .blog-vis i{font-size:42px;color:rgba(184,144,60,.32)}
.brand-integrated .blog-body{padding:24px}
.brand-integrated .blog-tag{font-size:8.5px;letter-spacing:.2em;text-transform:uppercase;font-weight:700;color:var(--amber);margin-bottom:10px;display:block}
.brand-integrated .blog-title{font-family:"Cormorant Garamond",serif;color:#f0ede8;font-size:21px;line-height:1.35;font-weight:400;margin-bottom:10px}
.brand-integrated .blog-meta{font-size:10px;color:rgba(253,246,232,.34)}
.brand-integrated .topics{display:flex;flex-wrap:wrap;gap:8px;margin-top:26px}
.brand-integrated .topic{font-size:9px;text-transform:uppercase;letter-spacing:.15em;color:rgba(253,246,232,.58);border:.5px solid rgba(184,144,60,.22);padding:7px 12px}


/* B2B */


.brand-integrated .b2b-grid{display:grid;grid-template-columns:1fr 1fr;gap:36px}
.brand-integrated .b2b-card{background:#fff;border:1px solid var(--border-2);padding:32px}
.brand-integrated .b2b-card h3{font-family:"Cormorant Garamond",serif;font-size:30px;font-weight:400;margin-bottom:14px}
.brand-integrated .b2b-card p{font-size:12px;font-weight:300;line-height:1.85;color:var(--ink-3);margin-bottom:18px}
.brand-integrated .b2b-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.brand-integrated .b2b-list span{font-size:10px;color:var(--ink-3);border-top:1px solid var(--border);padding:10px 0}
.brand-integrated .b2b-list span:before{content:"✓";color:var(--green-2);font-weight:700;margin-right:8px}


/* PRODUCT DETAIL */


.brand-integrated .pd-top{background:linear-gradient(135deg,var(--forest),#092212);display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--gold-border)}
.brand-integrated .pd-l{padding:76px 58px 76px 48px;border-right:.5px solid rgba(184,144,60,.17);display:flex;flex-direction:column;justify-content:center}
.brand-integrated .pd-r{padding:64px 48px;display:flex;align-items:center;justify-content:center}
.brand-integrated .pd-cat{font-size:9px;letter-spacing:.24em;text-transform:uppercase;color:rgba(184,144,60,.72);margin-bottom:16px}
.brand-integrated .pd-title{font-family:"Cormorant Garamond",serif;font-size:56px;font-weight:300;line-height:1.05;color:#f0ede8;margin-bottom:18px}
.brand-integrated .pd-sub{font-size:12.5px;font-weight:300;line-height:1.85;color:rgba(253,246,232,.56);margin-bottom:28px;max-width:560px}
.brand-integrated .pd-chips{display:flex;gap:7px;flex-wrap:wrap}
.brand-integrated .pd-chip{font-size:9px;letter-spacing:.12em;text-transform:uppercase;color:rgba(253,246,232,.64);padding:6px 11px;border:.5px solid rgba(184,144,60,.22)}
.brand-integrated .pd-bottle{transform:scale(1.1)}
.brand-integrated .pd-content{padding:70px 48px}
.brand-integrated .pd-layout{display:grid;grid-template-columns:.95fr 1.05fr;gap:46px}
.brand-integrated .pd-panel{background:#fff;border:1px solid var(--border-2);padding:28px}
.brand-integrated .pd-panel h3{font-family:"Cormorant Garamond",serif;font-size:30px;font-weight:400;margin-bottom:12px}
.brand-integrated .pd-panel p, .brand-integrated .pd-panel li{font-size:12px;font-weight:300;line-height:1.85;color:var(--ink-3)}
.brand-integrated .pd-panel ul{padding-left:18px}
.brand-integrated .ingredient-table{width:100%;border-collapse:collapse;margin-top:14px}
.brand-integrated .ingredient-table th, .brand-integrated .ingredient-table td{border:1px solid var(--border);padding:10px 12px;text-align:left;font-size:10.5px;line-height:1.55}
.brand-integrated .ingredient-table th{background:var(--sage);font-weight:700;text-transform:uppercase;letter-spacing:.12em;color:var(--green)}
.brand-integrated .faq{margin-top:18px;border-top:1px solid var(--border)}
.brand-integrated .faq-row{padding:15px 0;border-bottom:1px solid var(--border)}
.brand-integrated .faq-q{font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:var(--ink);font-weight:700;margin-bottom:6px}
.brand-integrated .notice{margin-top:28px;background:var(--sage-2);border:1px solid rgba(26,74,46,.2);padding:18px 20px;font-size:11px;line-height:1.75;color:var(--green-2);display:flex;gap:12px}
.brand-integrated .notice i{font-size:17px;margin-top:2px}


/* CONTACT */


.brand-integrated .cont-grid{display:grid;grid-template-columns:1fr 1fr;gap:70px;margin-top:52px}
.brand-integrated .c-list{display:flex;flex-direction:column}
.brand-integrated .c-row{display:flex;align-items:flex-start;gap:16px;padding:18px 0;border-bottom:.5px solid var(--border)}
.brand-integrated .c-row:first-child{border-top:.5px solid var(--border)}
